import json

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def __eq__(self, other):
        return isinstance(other, Employee) and self.name == other.name and self.salary == other.salary

class EmployeeEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Employee):
            return {'type': 'Employee', 'name': obj.name, 'salary': obj.salary}
        return super().default(obj)

class EmployeeDecoder:
    @staticmethod
    def decode(dct):
        if dct.get('type') == 'Employee':
            return Employee(dct['name'], dct['salary'])
        return dct

json.JSONDecoder().object_hook = EmployeeDecoder

emp = Employee('Bob', 75000)

json_str = json.dumps(emp, cls=EmployeeEncoder)

restored = json.loads(json_str)

print('JSON:', json_str)
print('Restored:', restored)
print('Is Employee?', isinstance(restored, Employee))

